package com.nutribite.ai.controller;
import com.nutribite.ai.profile.dto.request.UpdateProfileRequest; import com.nutribite.ai.profile.dto.response.ProfileResponse; import com.nutribite.ai.profile.service.UserProfileService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/onboarding") @RequiredArgsConstructor public class OnboardingController { private final UserProfileService profileService; @PostMapping public ResponseEntity<ProfileResponse> save(@Valid @RequestBody UpdateProfileRequest request){return ResponseEntity.ok(profileService.createOrUpdateProfile(request));} }
